"use client";

import { useEffect, useMemo, useState } from "react";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";

type Tab = "overview" | "master-schedule" | "faculty-load";

interface ReportsResponse {
  success: boolean;
  message: string;
  data: {
    master_schedule: any[];
    faculty_load: any[];
  };
}

export default function AdminReportsPage() {
  const [tab, setTab] = useState<Tab>("overview");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [masterSchedule, setMasterSchedule] = useState<any[]>([]);
  const [facultyLoad, setFacultyLoad] = useState<any[]>([]);

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const res = await api.get<ReportsResponse>("/admin/reports");
        setMasterSchedule(res.data.master_schedule ?? []);
        setFacultyLoad(res.data.faculty_load ?? []);
      } catch (e) {
        setError(e instanceof Error ? e.message : "Failed to load reports.");
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const overview = useMemo(() => {
    const confirmed = masterSchedule.filter((r) => String(r.status ?? "").toLowerCase() === "confirmed").length;
    const pending = masterSchedule.filter((r) => String(r.status ?? "").toLowerCase() === "pending").length;
    const totalUnits = facultyLoad.reduce((sum, r) => sum + Number(r.current_units ?? r.total_load ?? 0), 0);
    return { confirmed, pending, totalUnits };
  }, [masterSchedule, facultyLoad]);

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Reports">
      <div className="space-y-5">
        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-xl font-semibold">Reports</h1>
            <p className="text-sm" style={{ color: "var(--color-text-secondary)" }}>
              Live data from admin reporting endpoints
            </p>
          </div>
        </div>

        <div className="flex gap-2">
          {(["overview", "master-schedule", "faculty-load"] as Tab[]).map((t) => (
            <button
              key={t}
              className="px-3 py-1.5 rounded-lg text-xs font-medium"
              style={tab === t ? { background: "var(--color-primary)", color: "#fff" } : { background: "var(--color-surface-2)" }}
              onClick={() => setTab(t)}
            >
              {t === "overview" ? "Overview" : t === "master-schedule" ? "Master Schedule" : "Faculty Load"}
            </button>
          ))}
        </div>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>{error}</div>}

        {tab === "overview" && (
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            <StatCard label="Master Schedule Rows" value={masterSchedule.length} />
            <StatCard label="Faculty Load Rows" value={facultyLoad.length} />
            <StatCard label="Confirmed Sections" value={overview.confirmed} />
            <StatCard label="Pending Sections" value={overview.pending} />
          </div>
        )}

        {tab === "master-schedule" && (
          <div className="card overflow-hidden">
            <div className="card-body pb-2">
              <p className="text-sm font-semibold">Master Schedule Report</p>
              <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>
                {loading ? "Loading..." : `${masterSchedule.length} rows`}
              </p>
            </div>
            <div className="overflow-x-auto">
              <table className="table-base">
                <thead>
                  <tr>
                    {Object.keys(masterSchedule[0] ?? { note: "No data" }).map((k) => <th key={k}>{k}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {masterSchedule.map((row, i) => (
                    <tr key={i}>
                      {Object.keys(masterSchedule[0] ?? {}).map((k) => <td key={k}>{String(row[k] ?? "")}</td>)}
                    </tr>
                  ))}
                  {!loading && masterSchedule.length === 0 && <tr><td className="text-center">No data.</td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {tab === "faculty-load" && (
          <div className="card overflow-hidden">
            <div className="card-body pb-2">
              <p className="text-sm font-semibold">Faculty Load Report</p>
              <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>
                {loading ? "Loading..." : `${facultyLoad.length} rows · ${overview.totalUnits.toFixed(1)} total units`}
              </p>
            </div>
            <div className="overflow-x-auto">
              <table className="table-base">
                <thead>
                  <tr>
                    {Object.keys(facultyLoad[0] ?? { note: "No data" }).map((k) => <th key={k}>{k}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {facultyLoad.map((row, i) => (
                    <tr key={i}>
                      {Object.keys(facultyLoad[0] ?? {}).map((k) => <td key={k}>{String(row[k] ?? "")}</td>)}
                    </tr>
                  ))}
                  {!loading && facultyLoad.length === 0 && <tr><td className="text-center">No data.</td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </AppShell>
  );
}

function StatCard({ label, value }: { label: string; value: number }) {
  return (
    <div className="card card-body">
      <p className="text-2xl font-bold">{value}</p>
      <p className="text-xs" style={{ color: "var(--color-text-secondary)" }}>{label}</p>
    </div>
  );
}
